begin;
select set_config('request.jwt.claim.sub',(select id::text from public.profiles where role='owner' and active limit 1),true);
do $$
declare c uuid:=gen_random_uuid(); cp uuid:=gen_random_uuid(); ct uuid:=gen_random_uuid(); ast uuid:=gen_random_uuid(); lease uuid:=gen_random_uuid(); sal uuid:=gen_random_uuid(); receipt uuid:=gen_random_uuid(); p uuid; v numeric; other uuid; failed boolean; snap jsonb;
begin
 select id into p from rwa2.records where kind='partner' limit 1;
 perform public.rwa2_post(jsonb_build_object('id',gen_random_uuid(),'op','opening','date','2026-09-01','note','جرد تجريبي','lines',jsonb_build_array(jsonb_build_object('account','cash_usd','debit',1000,'credit',0,'native_amount',1000),jsonb_build_object('account','capital','debit',0,'credit',1000,'party_id',p))));
 perform public.rwa2_save_record(jsonb_build_object('id',c,'kind','customer','data',jsonb_build_object('name','عميل اختبار')));
 perform public.rwa2_save_record(jsonb_build_object('id',sal,'kind','employee','data',jsonb_build_object('name','مبيعات اختبار','pay_type','per_task','rate',10,'start_date','2026-09-01')));
 perform public.rwa2_save_record(jsonb_build_object('id',ct,'kind','contract','data',jsonb_build_object('name','عقد اختبار','customer_id',c,'type','units','status','active','start_date','2026-09-01','end_date','2026-09-30','sales_employee_id',sal,'commission_pct',10,'items',jsonb_build_array(jsonb_build_object('service','service','qty',1,'rate',200)))));
 perform public.rwa2_post(jsonb_build_object('id',gen_random_uuid(),'op','invoice','date','2026-09-01','note','فاتورة','contract_id',ct));
 perform public.rwa2_post(jsonb_build_object('id',receipt,'op','receipt','date','2026-09-03','note','قبض','party_id',c,'contract_id',ct,'amount',100));
 perform public.rwa2_post(jsonb_build_object('id',gen_random_uuid(),'op','commission_accrual','date','2026-09-03','note','عمولة','reference_id',receipt));
 if (select sum(credit-debit) from rwa2.lines where account='wages_due' and party_id=sal)<>10 then raise exception 'commission wrong';end if;
 perform public.rwa2_post(jsonb_build_object('id',gen_random_uuid(),'op','credit_note','date','2026-09-04','note','إلغاء','contract_id',ct,'amount',150));
 if (select sum(credit-debit) from rwa2.lines where account='customer_credit' and party_id=c)<>50 then raise exception 'credit wrong';end if;
 perform public.rwa2_save_record(jsonb_build_object('id',cp,'kind','campaign','data',jsonb_build_object('name','حملة اختبار','customer_id',c,'budget',100,'fee',30)));
 perform public.rwa2_post(jsonb_build_object('id',gen_random_uuid(),'op','ad_receipt','date','2026-09-05','note','قبض حملة','campaign_id',cp));
 perform public.rwa2_post(jsonb_build_object('id',gen_random_uuid(),'op','ad_spend','date','2026-09-06','note','إنفاق فعلي','campaign_id',cp,'amount',70));
 perform public.rwa2_post(jsonb_build_object('id',gen_random_uuid(),'op','ad_fee','date','2026-09-07','note','أتعاب مكتسبة','campaign_id',cp,'amount',30));
 if (select sum(credit-debit) from rwa2.lines where account='ad_funds' and campaign_id=cp)<>30 then raise exception 'campaign balance wrong';end if;
 perform public.rwa2_post(jsonb_build_object('id',gen_random_uuid(),'op','fx_transfer','date','2026-09-08','note','شراء سوري','amount',13700,'rate',137,'direction','usd_to_syp'));
 perform public.rwa2_post(jsonb_build_object('id',gen_random_uuid(),'op','fx_transfer','date','2026-09-09','note','بيع سوري','amount',13700,'rate',100,'direction','syp_to_usd'));
 if (select sum(debit-credit) from rwa2.lines where account='cash_syp')<>0 then raise exception 'FX leaves book residue';end if;
 if (select sum(credit-debit) from rwa2.lines where account='fx_gain')<>37 then raise exception 'FX gain wrong';end if;
 perform public.rwa2_save_record(jsonb_build_object('id',ast,'kind','asset','data',jsonb_build_object('name','قطعة اختبار','life_months',10,'residual',0,'ready_date','2026-09-01')));
 perform public.rwa2_post(jsonb_build_object('id',gen_random_uuid(),'op','asset_purchase','date','2026-09-10','note','معدات','asset_id',ast,'amount',100));
 perform public.rwa2_post(jsonb_build_object('id',gen_random_uuid(),'op','depreciation','date','2026-09-30','note','إهلاك','reference_id',ast));
 if (select sum(credit-debit) from rwa2.lines where account='depreciation_acc' and asset_id=ast)<>10 then raise exception 'depreciation wrong';end if;
 perform public.rwa2_save_record(jsonb_build_object('id',lease,'kind','lease','data',jsonb_build_object('name','إيجار اختبار','remaining',1600,'months',6,'start_date','2026-11-01','end_date','2027-04-30')));
 perform public.rwa2_post(jsonb_build_object('id',gen_random_uuid(),'op','opening','date','2026-11-01','note','افتتاح إيجار','lines',jsonb_build_array(jsonb_build_object('account','prepaid_rent','debit',1600,'credit',0),jsonb_build_object('account','capital','debit',0,'credit',1600,'party_id',p))));
 for i in 0..5 loop perform public.rwa2_post(jsonb_build_object('id',gen_random_uuid(),'op','rent_accrual','date',(date '2026-11-01'+make_interval(months=>i))::text,'note','إيجار شهر','reference_id',lease));end loop;
 if (select sum(debit-credit) from rwa2.lines where account='prepaid_rent')<>0 then raise exception 'rent rounding residue';end if;
 select id into other from public.profiles where role<>'owner' and active limit 1;
 insert into rwa2.members(user_id,role,active) values(other,'sales',true) on conflict(user_id) do update set role='sales',active=true;
 perform set_config('request.jwt.claim.sub',other::text,true);
 snap:=public.rwa2_snapshot();if jsonb_array_length(snap->'journals')<>0 or jsonb_array_length(snap->'accounts')<>0 then raise exception 'sales finance leak';end if;
 failed:=false;begin perform public.rwa2_post(jsonb_build_object('id',gen_random_uuid(),'op','expense','date','2026-09-10','note','منع مبيعات','amount',1));exception when others then failed:=true;end;if not failed then raise exception 'sales write allowed';end if;
 perform set_config('request.jwt.claim.sub','',true);
 failed:=false;begin perform public.rwa2_snapshot();exception when others then failed:=true;end;if not failed then raise exception 'anonymous snapshot allowed';end if;
 if has_schema_privilege('authenticated','rwa2','USAGE') then raise exception 'private schema exposed';end if;
 if has_function_privilege('anon','public.rwa2_post(jsonb)','EXECUTE') then raise exception 'anonymous RPC grant';end if;
end $$;
set constraints all immediate;
select 'PASS: commissions, credit notes, Meta funds/fees, FX gains, depreciation, rent rounding, sales isolation, anonymous denial' as result;
rollback;
